import '../model/dataset_entry.dart';
import '../model/dataset_provenance.dart';
import '../util/ids.dart';
import '../variation/dataset_variation_generator.dart';
import '../variation/variation_generate_options.dart';
import 'text_build.dart';
import 'text_lexicon.dart';

/// Produces meaning-preserving surface variations by swapping lexicon alternates.
///
/// Requires canonical entries generated by [PhraseGenerator] or
/// [ParagraphGenerator] (exercise metadata with templates and semantic keys).
class MeaningPreservingVariationGenerator implements DatasetVariationGenerator {
  /// Creates a variation generator for [lexicon].
  MeaningPreservingVariationGenerator({
    required this.lexicon,
    this.variationsPerEntry = 3,
    this.generatorVersion = '1.0.0',
    this.instanceId,
    this.seed,
  });

  /// Lexicon matching the entry language.
  final TextLexicon lexicon;

  /// Number of alternate surface forms to emit per canonical entry.
  final int variationsPerEntry;

  /// Provenance version string.
  final String generatorVersion;

  /// Optional stable instance id.
  final String? instanceId;

  /// Optional seed for deterministic slot-selection order.
  final int? seed;

  @override
  Future<List<DatasetEntry>> generate(
    DatasetEntry entry, {
    VariationGenerateOptions options = defaultVariationGenerateOptions,
  }) async {
    if (variationsPerEntry <= 0) {
      return const [];
    }

    final metadata = entry.metadata;
    final kind = metadata[TextExerciseMetadata.textKind];
    if (kind != 'phrase' &&
        kind != 'paragraph' &&
        kind != TextExerciseMetadata.languageBasics) {
      return const [];
    }

    late final Map<String, String> baseSlots;
    late final Map<String, String> semanticKeys;

    if (kind == 'phrase' || kind == TextExerciseMetadata.languageBasics) {
      baseSlots = Map<String, String>.from(
        (metadata[TextExerciseMetadata.slots] as Map).cast<String, String>(),
      );
      semanticKeys = Map<String, String>.from(
        (metadata[TextExerciseMetadata.semanticKeys] as Map)
            .cast<String, String>(),
      );
    } else {
      final specs = (metadata[TextExerciseMetadata.paragraphSentences] as List)
          .cast<Map<String, dynamic>>();
      final flat = flattenParagraphSpecs(specs);
      baseSlots = flat.slots;
      semanticKeys = flat.semanticKeys;
    }

    final results = <DatasetEntry>[];
    var index = options.startVariationIndex;
    final generatorKey = options.instanceId ?? instanceId ?? generatorVersion;

    for (var variation = 0; variation < variationsPerEntry; variation++) {
      final variedSlots = _varySlots(
        baseSlots,
        semanticKeys,
        variationIndex: variation + 1,
      );
      final overrides = variedSlots;
      final text = rebuildExerciseText(metadata, slotOverrides: overrides);
      if (text == entry.input) {
        continue;
      }

      final id = stableDatasetId([
        entry.variationGroup,
        index,
        'meaning',
        variation,
        seed,
        generatorKey,
      ]);

      results.add(
        entry.copyWith(
          id: id,
          input: text,
          output: text,
          variationIndex: index,
          metadata: {
            ...metadata,
            if (kind == 'phrase' || kind == TextExerciseMetadata.languageBasics)
              TextExerciseMetadata.slots: variedSlots,
            'variationStrategy': 'meaning_preserving',
            'variationOrdinal': variation + 1,
          },
          provenance: DatasetProvenance(
            source: entry.provenance?.source,
            sourceId: entry.provenance?.sourceId,
            sourceUri: entry.provenance?.sourceUri,
            generator: 'MeaningPreservingVariationGenerator',
            generatorVersion: generatorVersion,
            transformation: 'meaning_preserving',
            parentEntryId: entry.id,
            pipelineVersion: entry.provenance?.pipelineVersion,
          ),
        ),
      );
      index++;
    }

    return results;
  }

  Map<String, String> _varySlots(
    Map<String, String> baseSlots,
    Map<String, String> semanticKeys, {
    required int variationIndex,
  }) {
    final result = Map<String, String>.from(baseSlots);
    final slotNames = semanticKeys.keys.toList();
    if (slotNames.isEmpty) {
      return result;
    }

    final start = seed == null
        ? variationIndex % slotNames.length
        : (variationIndex + seed!) % slotNames.length;

    for (var offset = 0; offset < slotNames.length; offset++) {
      final slot = slotNames[(start + offset) % slotNames.length];
      final lemma = semanticKeys[slot];
      if (lemma == null) {
        continue;
      }
      final alternate = lexicon.alternate(
        lemma,
        variationIndex + offset,
        avoid: baseSlots[slot],
      );
      if (alternate != baseSlots[slot]) {
        result[slot] = alternate;
        break;
      }
    }

    return result;
  }
}
